  function importModal(){openModal(`<p class="eyebrow">IMPORTACIÓN MULTIMUESTRA PRO · v91.0</p><h2>Cargar Excel del laboratorio</h2><p class="muted">Un solo archivo puede contener muchas válvulas/muestras. Primero lo leemos; después confirmás hoja, parámetros, profundidad y a qué lote/sector corresponde cada muestra.</p><form id="labImportForm"><div class="form-grid"><label>Tipo de análisis<select name="category">${TYPES.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Fecha de muestra<input type="date" name="sample_date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Laboratorio<input name="laboratory" placeholder="Nombre del laboratorio"></label><label>Profundidad / sector<input name="depth" placeholder="Ej.: 0–20 cm"></label><label class="wide">Excel<input id="labExcel" type="file" name="excel" accept=".xlsx,.xls,.csv" required></label></div><div id="labPreview" class="status" style="margin:12px 0">Seleccioná el archivo. La app detectará hojas, muestras y parámetros nutricionales.</div><div id="labSampleMap" class="hidden" style="margin:14px 0"><h3>Muestras detectadas</h3><p class="muted">Revisá la asociación antes de guardar. Podés desmarcar una muestra o dejarla sin asociar.</p><div class="table-wrap"><table class="table"><thead><tr><th>Usar</th><th>Muestra / parámetros</th><th>Lote / válvula</th><th>Aprender equivalencia</th></tr></thead><tbody id="labSampleMapBody"></tbody></table></div></div><button class="primary" type="submit">Guardar muestras y archivar Excel</button><p id="labImportMsg" class="error hidden"></p></form>`);let parsed=null;document.querySelector('#labExcel').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;const box=document.querySelector('#labPreview'),map=document.querySelector('#labSampleMap'),body=document.querySelector('#labSampleMapBody');try{if(!window.XLSX)throw new Error('No se pudo cargar el lector de Excel. Verificá la conexión a internet.');const buf=await f.arrayBuffer();const wb=window.XLSX.read(buf,{type:'array'});parsed=parseWorkbookMulti(wb);const n=parsed.samples?.length||0,sheets=parsed.sheetNames.join(', ');box.innerHTML=n?`<b>${n} muestra(s) detectada(s)</b> en ${parsed.sheetNames.length} hoja(s): ${esc(sheets)}.<br><small>Cada muestra se guardará por separado, pero el Excel original se archivará una sola vez.</small>`:`No se detectaron muestras automáticamente en ${parsed.sheetNames.length} hoja(s). Podés archivar el Excel y completar el análisis manualmente.`;if(n){body.innerHTML=sampleAssociationRows(parsed);bindSamplePreview(parsed);map.classList.remove('hidden')}else map.classList.add('hidden')}catch(err){box.textContent=err.message}};document.querySelector('#labImportForm').onsubmit=e=>saveImported(e,parsed)}
