  async function saveManual(e,row){e.preventDefault();const f=new FormData(e.target),values={},units={};for(const k of Object.keys(labels)){const raw=f.get(k);values[k]=raw===''?null:Number(raw);units[k]=String(f.get(`${k}_unit`)||defaultUnit(k))}const payload={company_id:state.companyId,lot_id:f.get('lot_id'),sample_date:f.get('sample_date'),analysis_type:`Laboratorio - ${f.get('category')}`,laboratory:f.get('laboratory')||null,main_result:'Análisis revisado manualmente',results_json:{...(row?.results_json||{}),kind:'lab_intelligent',schema_version:1,analysis_category:f.get('category'),depth:f.get('depth')||null,values,units,review_status:'reviewed',reviewed_at:new Date().toISOString()}};let error;if(row?.id)({error}=await supabase.from('lab_analyses').update(payload).eq('id',row.id));else{payload.created_by=state.session.user.id;({error}=await supabase.from('lab_analyses').insert(payload))}if(error){const m=document.querySelector('#labManualMsg');m.textContent=error.message;m.classList.remove('hidden');return}document.querySelector('#modalRoot').innerHTML='';await loadData();render()}
